[CmdletBinding(SupportsShouldProcess=$true)]
param([ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',[ValidateRange(1,20)][int]$RunsPerArm=5,[ValidateRange(30,600)][int]$SampleSeconds=120,[switch]$AllowAutomaticReboot,[string]$EvidenceRoot="$PSScriptRoot\lab-evidence",[string]$RunDirectory,[string]$ControllerPath="$PSScriptRoot\Invoke-Exp120HpHotkey.ps1")
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$TaskName='Lacksan-EXP-120-LabHarness';$Active=Join-Path $EvidenceRoot 'active.json';$Service='HotKeyServiceUWP'
function Dir($p){if(-not(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}};function W($p,$v){$v|ConvertTo-Json -Depth 12|Set-Content $p -Encoding UTF8};function R($p){Get-Content $p -Raw|ConvertFrom-Json};function Boot{((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime().ToString('o')};function Med($v){$a=@($v|?{$null-ne$_}|%{[double]$_}|sort);if(!$a.Count){return $null};$m=[math]::Floor($a.Count/2);if($a.Count%2){$a[$m]}else{($a[$m-1]+$a[$m])/2}};function Mad($v){$m=Med $v;Med @($v|%{[math]::Abs([double]$_-$m)})}
function C($a,$d){& $ControllerPath -Action $a -StatePath (Join-Path $d 'controller-state.json') -LogPath (Join-Path $d 'controller-events.jsonl')}
function CurrentDir{if($RunDirectory){return (Resolve-Path $RunDirectory).Path};(R $Active).runDirectory}
function Protected{[ordered]@{tailscale=try{(Get-Service Tailscale).Status.ToString()}catch{'absent'};remoteDesktop=try{(Get-Service TermService).Status.ToString()}catch{'absent'};processes=@(Get-Process -ErrorAction SilentlyContinue|?{$_.ProcessName-match'(?i)tailscale|msrdc|windowsapp|omnissa|horizon|vmware-view|wswc'}|select ProcessName,Id,Responding)}}
function Collect($phase,$n,$d){$b=Boot;$svc=Get-CimInstance Win32_Service -Filter "Name='$Service'";$p0=if($svc.ProcessId){Get-Process -Id $svc.ProcessId -ErrorAction SilentlyContinue};$cpu0=if($p0){$p0.TotalProcessorTime.TotalMilliseconds}else{$null};$io0=if($svc.ProcessId){Get-CimInstance Win32_Process -Filter "ProcessId=$($svc.ProcessId)" -ErrorAction SilentlyContinue}else{$null};$samples=@();$end=(Get-Date).AddSeconds($SampleSeconds);while((Get-Date)-lt$end){$samples+=[pscustomobject]@{cpu=[double](Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;disk=[double](Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec};Start-Sleep 2};$svc2=Get-CimInstance Win32_Service -Filter "Name='$Service'";$p1=if($svc2.ProcessId){Get-Process -Id $svc2.ProcessId -ErrorAction SilentlyContinue};$io1=if($svc2.ProcessId){Get-CimInstance Win32_Process -Filter "ProcessId=$($svc2.ProcessId)" -ErrorAction SilentlyContinue}else{$null};$e=Get-Process explorer -ErrorAction SilentlyContinue|sort StartTime|select -First 1;[ordered]@{schema=1;experiment='EXP-120';phase=$phase;ordinal=$n;bootUtc=$b;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');desktop=[ordered]@{explorerResponding=if($e){$e.Responding}else{$false};bootToExplorerStartMs=if($e){($e.StartTime.ToUniversalTime()-[datetime]$b).TotalMilliseconds}else{$null}};system=[ordered]@{cpuMedian=Med @($samples.cpu);cpuMad=Mad @($samples.cpu);diskMedian=Med @($samples.disk);diskMad=Mad @($samples.disk)};service=[ordered]@{state=$svc2.State;startMode=$svc2.StartMode;pid=$svc2.ProcessId;cpuDeltaMs=if($p0-and$p1-and$p0.Id-eq$p1.Id){$p1.TotalProcessorTime.TotalMilliseconds-$cpu0}else{$null};readDeltaBytes=if($io0-and$io1-and$io0.ProcessId-eq$io1.ProcessId){[uint64]$io1.ReadTransferCount-[uint64]$io0.ReadTransferCount}else{$null};writeDeltaBytes=if($io0-and$io1-and$io0.ProcessId-eq$io1.ProcessId){[uint64]$io1.WriteTransferCount-[uint64]$io0.WriteTransferCount}else{$null}};protected=Protected;hotkeyMatrix=[ordered]@{brightness='needs-evidence';volumeMute='needs-evidence';microphoneMute='needs-evidence';keyboardBacklight='needs-evidence';displaySwitch='needs-evidence';wirelessKey='needs-evidence';programmableKey='needs-evidence'}}}
function Summary($d){$runs=@(Get-ChildItem $d -Filter 'run-*.json'|sort Name|%{R $_.FullName});$g=[ordered]@{};foreach($ph in 'Baseline','Treatment'){$x=@($runs|? phase-eq$ph);$g[$ph]=[ordered]@{runs=$x.Count;bootToExplorerStartMs=[ordered]@{median=Med @($x.desktop.bootToExplorerStartMs);mad=Mad @($x.desktop.bootToExplorerStartMs)};cpuMedian=[ordered]@{median=Med @($x.system.cpuMedian);mad=Mad @($x.system.cpuMedian)};diskMedian=[ordered]@{median=Med @($x.system.diskMedian);mad=Mad @($x.system.diskMedian)};serviceCpuDeltaMs=[ordered]@{median=Med @($x.service.cpuDeltaMs);mad=Mad @($x.service.cpuDeltaMs)}}};$o=[ordered]@{schema=1;experiment='EXP-120';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');groups=$g;classification='needs-evidence';limitations=@('Explorer timing is a desktop-readiness proxy','Physical hotkey matrix requires observed key/function evidence')};W (Join-Path $d 'summary.json') $o;$o}
function Task($d){$a=New-ScheduledTaskAction -Execute (Get-Command powershell.exe).Source -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ControllerPath `"$ControllerPath`"";$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$p=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;if($PSCmdlet.ShouldProcess($TaskName,'Register continuation task')){Register-ScheduledTask $TaskName -Action $a -Trigger $t -Principal $p -Force|Out-Null}}
function Reboot{if($AllowAutomaticReboot){Restart-Computer -Force}else{'Reboot required; continuation resumes at next logon.'}}
switch($Action){
'Start'{Dir $EvidenceRoot;$check=C Check $EvidenceRoot;if($WhatIfPreference){return $check};$d=Join-Path $EvidenceRoot (Get-Date -Format 'yyyyMMdd-HHmmss');Dir $d;C Capture $d;W (Join-Path $d 'state.json') ([ordered]@{phase='Baseline';completed=0;runsPerArm=$RunsPerArm;lastBoot=$null});W $Active @{runDirectory=$d};Task $d;Reboot}
'Continue'{$d=CurrentDir;$s=R (Join-Path $d 'state.json');$b=Boot;if($s.lastBoot-eq$b){throw 'Duplicate boot refused'};if($s.phase-eq'Treatment'){C VerifyReboot $d};$n=[int]$s.completed+1;W (Join-Path $d ("run-{0}-{1:D2}.json"-f$s.phase,$n)) (Collect $s.phase $n $d);$s.completed=$n;$s.lastBoot=$b;if($n-ge$s.runsPerArm){if($s.phase-eq'Baseline'){$s.phase='Treatment';$s.completed=0;C Apply $d}else{C Rollback $d;$null=Summary $d;Unregister-ScheduledTask $TaskName -Confirm:$false -ErrorAction SilentlyContinue;Remove-Item $Active -Force;W (Join-Path $d 'state.json') $s;return R (Join-Path $d 'summary.json')}};W (Join-Path $d 'state.json') $s;Reboot}
'Status'{if(Test-Path $Active){R (Join-Path (CurrentDir) 'state.json')}else{[pscustomobject]@{active=$false}}}
'Summarize'{Summary (CurrentDir)}
'Stop'{$d=CurrentDir;C Rollback $d;Unregister-ScheduledTask $TaskName -Confirm:$false -ErrorAction SilentlyContinue;Remove-Item $Active -Force -ErrorAction SilentlyContinue;[pscustomobject]@{stopped=$true;runDirectory=$d}}
}
